// ==UserScript==
// @name         WorldCat eBooks Assistant (API V2.1)
// @namespace    https://github.com/caspartse/eBooksAssistant
// @version      2.1.0
// @description  在 WorldCat 详情页基于全网 API 植入豆瓣评分、高清封面及四大电商数字资源
// @author       Gemini & 刘峰
// @match        *://*.firstsearch.oclc.org/*
// @require      https://cdnjs.cloudflare.com/ajax/libs/jquery/3.7.1/jquery.min.js
// @connect      api.youdianzishu.com
// @connect      isbnsearch.org
// @run-at       document-end
// @grant        GM_xmlhttpRequest
// ==/UserScript==

(function() {
    'use strict';

    // ==========================================
    // Base64 图标资源
    // ==========================================
    const base64_icon_weread = "data:image/png;base64,";
    const base64_icon_duokan = "data:image/png;base64,";
    const base64_icon_jd = "data:image/png;base64,";
    const base64_icon_dangdang = "data:image/png;base64,";
    const base64_icon_ximalaya = "data:image/png;base64,";
    // ⬇️ 修正后的豆瓣图标
    const base64_icon_douban = "data:image/png;base64,";
    const base64_icon_douban_rating = "data:image/png;base64,";
    // --- 图书数据库 Base64 图标 ---
    const base64_icon_google = "data:image/png;base64,"; // 此处填入 Google 镜像图标
    const base64_icon_duxiu= "data:image/jpeg;base64,"; // 此处填入读秀图标
    const base64_icon_annas= "data:image/png;base64,"; // 此处填入 Anna's Archive 图标
    const base64_icon_zlib = "data:image/jpeg;base64,"; // 此处填入 Z-Lib 图标
    const base64_icon_open= "data:image/png;base64,";
    // ----------------------------------------------

    // ==========================================
    // 样式注入
    // ==========================================
    const addNewStyle = () => {
        const new_style = `<style type="text/css" media="screen">
        .douban_rating {
            width: 75px; height: 15px; display: inline-block;
            background-image: url("${base64_icon_douban_rating}");
            background-size: 75px 165px; background-repeat: no-repeat;
        }
        .douban_rating_star_0 { background-position: 0 -150px; }
        .douban_rating_star_1 { background-position: 0 -135px; }
        .douban_rating_star_2 { background-position: 0 -120px; }
        .douban_rating_star_3 { background-position: 0 -105px; }
        .douban_rating_star_4 { background-position: 0 -90px; }
        .douban_rating_star_5 { background-position: 0 -75px; }
        .douban_rating_star_6 { background-position: 0 -60px; }
        .douban_rating_star_7 { background-position: 0 -45px; }
        .douban_rating_star_8 { background-position: 0 -30px; }
        .douban_rating_star_9 { background-position: 0 -15px; }
        .douban_rating_star_10 { background-position: 0 0; }
        .eba-resource-icon { width: 18px; height: 18px; border-radius: 50%; box-shadow: 0 0 2px rgba(0,0,0,0.3); transition: transform 0.2s; }
        .eba-resource-icon:hover { transform: scale(1.1); }
        .eba-gray { filter: grayscale(100%); opacity: 0.5; }
        </style>`;
        $("html").append(new_style);
    };

    // ==========================================
    // 工具函数
    // ==========================================
    const getElementByXPath = (xpath) => {
        return document.evaluate(xpath, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
    };

    const uuidv4 = () => {
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            let r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });
    };

    // 全局通用配置
    const REST_URL = "https://api.youdianzishu.com/v2";
    const x_unique_id = uuidv4();
    const commonHeaders = {
        "User-agent": window.navigator.userAgent,
        "X-Referer": "https://book.douban.com/",
        "X-Unique-ID": x_unique_id
    };

    // ==========================================
    // UI 注入与更新
    // ==========================================
    // 注意增加了 isbn 参数
    const injectUI = (targetNode, isbn) => {
        const uiHtml = `
            <div id="eba-worldcat-container" style="margin-top:12px; padding-top:12px; border-top:1px dashed #ccc; font-family: Arial, sans-serif;">
                <div id="eba-douban-row" style="display:flex; align-items:center; margin-bottom:10px;">
                    <img src="${base64_icon_douban}" style="width:16px; height:16px; margin-right:6px;" class="eba-gray" id="eba-db-icon">
                    <span style="font-size:13px; font-weight:bold; color:#666;" id="eba-db-text">豆瓣评分: 查询中...</span>
                    <span id="eba-db-stars" class="douban_rating" style="margin-left:8px; display:none;"></span>
                </div>

                <div id="eba-resources-row" style="display:flex; align-items:center;">
                    <span style="font-size:13px; font-weight:bold; color:#666; margin-right:10px;">数字资源:</span>
                    <a id="eba-link-weread" style="margin-right:8px; display:inline-block;" target="_blank" title="微信读书 (暂无)">
                        <img src="${base64_icon_weread}" class="eba-resource-icon eba-gray">
                    </a>
                    <a id="eba-link-duokan" style="margin-right:8px; display:inline-block;" target="_blank" title="多看阅读 (暂无)">
                        <img src="${base64_icon_duokan}" class="eba-resource-icon eba-gray">
                    </a>
                    <a id="eba-link-jd" style="margin-right:8px; display:inline-block;" target="_blank" title="京东读书 (暂无)">
                        <img src="${base64_icon_jd}" class="eba-resource-icon eba-gray">
                    </a>
                    <a id="eba-link-dangdang" style="margin-right:8px; display:inline-block;" target="_blank" title="当当云阅读 (暂无)">
                        <img src="${base64_icon_dangdang}" class="eba-resource-icon eba-gray">
                    </a>
                    <a id="eba-link-ximalaya" style="margin-right:8px; display:inline-block;" target="_blank" title="喜马拉雅 (暂无)">
                        <img src="${base64_icon_ximalaya}" class="eba-resource-icon eba-gray">
                    </a>
                </div>

                <div id="eba-databases-row" style="display:flex; align-items:center; margin-top:10px;">
                    <span style="font-size:13px; font-weight:bold; color:#666; margin-right:10px;">图书搜索:</span>
                    <a href="https://books.google.com/books?vid=ISBN${isbn}" target="_blank" title="Google Books" style="margin-right:8px; display:inline-block;">
                        <img src="${base64_icon_google}" class="eba-resource-icon">
                    </a>
                    <a href="http://book.duxiu.com/search?exp=0&sw=${isbn}" target="_blank" title="读秀学术" style="margin-right:8px; display:inline-block;">
                        <img src="${base64_icon_duxiu}" class="eba-resource-icon">
                    </a>
                    <a href="https://annas-archive.gl/search?q=${isbn}" target="_blank" title="Anna's Archive" style="margin-right:8px; display:inline-block;">
                        <img src="${base64_icon_annas}" class="eba-resource-icon">
                    </a>
                    <a href="https://z-lib.bz/s/?q=${isbn}" target="_blank" title="Z-Library" style="margin-right:8px; display:inline-block;">
                        <img src="${base64_icon_zlib}" class="eba-resource-icon">
                    </a>
                    <a href="https://openlibrary.org/search?q=${isbn}&mode=isbn" target="_blank" title="Open Library" style="margin-right:8px; display:inline-block;">
                        <img src="${base64_icon_open}" class="eba-resource-icon">
                    </a>
                </div>
            </div>
        `;
    // 关键！执行注入动作
        $(targetNode).append(uiHtml);
    };

    const lightUpIcon = (vendor, url, titlePrefix) => {
        const linkElem = $(`#eba-link-${vendor}`);
        linkElem.attr('href', url);
        linkElem.attr('title', titlePrefix);
        linkElem.find('img').removeClass('eba-gray');
    };

    // 封面替换逻辑
    const replaceCover = (proxyUrl) => {
        if (!proxyUrl) return;

        let mainPanel = document.querySelector('table.mainPanel') || document;
        let imgNode = mainPanel.querySelector('img[src*="coverart.oclc.org"]');
        let tdNode = null;

        if (imgNode) {
            tdNode = imgNode.closest('td');
        } else {
            // 回退方案：通过书名所在的 td 找到前一个 td（封面所在位置）
            let titleFonts = mainPanel.querySelectorAll('font[size="4"] b');
            for (let font of titleFonts) {
                let parentTd = font.closest('td');
                if (parentTd && parentTd.previousElementSibling && parentTd.previousElementSibling.getAttribute('width') === '10%') {
                    tdNode = parentTd.previousElementSibling;
                    break;
                }
            }
        }

        // 预加载新封面以验证其可用性（处理远端找不到图片的情况）
        let testImg = new Image();
        testImg.onload = function() {
            if (imgNode) {
                GM_xmlhttpRequest({
                    method: "HEAD",
                    url: imgNode.src,
                    onload: function(res) {
                        let size = parseInt(res.responseHeaders.match(/content-length:\s*(\d+)/i)?.[1] || "0");
                        if (size < 5120 || imgNode.naturalWidth < 50) {
                            imgNode.src = proxyUrl;
                            imgNode.style.maxWidth = '150px';
                            imgNode.style.maxHeight = '200px';
                            imgNode.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.3)';
                        }
                    },
                    onerror: function() {
                        // 如果原占位图连 HEAD 请求都失败了，安全起见直接替换
                        imgNode.src = proxyUrl;
                        imgNode.style.maxWidth = '150px';
                        imgNode.style.maxHeight = '200px';
                        imgNode.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.3)';
                    }
                });
            } else if (tdNode) {
                $(tdNode).prepend(`<img src="${proxyUrl}" style="max-width:150px; max-height:200px; box-shadow: 2px 2px 5px rgba(0,0,0,0.3);"/>`);
            }
        };
        testImg.onerror = function() {
            console.error(`[eBooks Assistant] 封面替换失败：远端无法获取图片 (${proxyUrl})`);
        };
        testImg.src = proxyUrl;
    };

    // ==========================================
    // 异步请求核心逻辑 (纯 API 版)
    // ==========================================

    // 1. 获取微信读书资源 (作为豆瓣评分和封面的 Pivot)
    const queryWeReadAndPivot = (isbn, metaTitle, metaAuthor) => {
        let t = encodeURIComponent(metaTitle || "");
        let a = encodeURIComponent(metaAuthor || "");

        GM_xmlhttpRequest({
            method: "GET",
            url: `${REST_URL}/weread?isbn=${isbn}&title=${t}&author=${a}&version=1.1.0&r=${Math.random()}`,
            headers: commonHeaders,
            onload: (res) => {
                try {
                    const result = JSON.parse(res.responseText);
                    if (result.errmsg === "" && result.data) {
                        const { vbookid, cover_url_proxy_weserv, url, price } = result.data;

                        // [动作 A] 点亮微信读书资源
                        if (url) lightUpIcon('weread', url, `微信读书 (￥${price || '0.00'})`);

                        // [动作 B] 触发封面替换逻辑
                        if (cover_url_proxy_weserv) replaceCover(cover_url_proxy_weserv);

                        // [动作 C] 触发豆瓣评分查询 (强依赖 vbookid)
                        if (vbookid) {
                            queryDouban(vbookid);
                        } else {
                            // 容错：微信有返回但没 vbookid
                            $("#eba-db-text").text("豆瓣评分: 暂无映射数据");
                        }
                    } else {
                        // 容错：微信读书完全没匹配到
                        $("#eba-db-text").text("豆瓣评分: 暂无资源匹配");
                    }
                } catch(e) {
                    $("#eba-db-text").text("豆瓣评分: 数据解析失败");
                }
            }
        });
    };

    // 2. 利用 vbookid 查豆瓣信息 (解耦执行)
    const queryDouban = (vbookid) => {
        GM_xmlhttpRequest({
            method: "GET",
            url: `${REST_URL}/weread/douban_info?vbookid=${vbookid}&version=1.1.0&r=${Math.random()}`,
            headers: commonHeaders,
            onload: (res) => {
                try {
                    const result = JSON.parse(res.responseText);
                    if (result.errmsg === "" && result.data) {
                        const { douban_rating_score, url } = result.data;
                        $("#eba-db-icon").removeClass('eba-gray'); // 映射成功后才点亮豆瓣图标

                        if (douban_rating_score > 0) {
                            $("#eba-db-text").html(`<a href="${url}" target="_blank" style="color:#007722; text-decoration:none;">豆瓣评分: ${douban_rating_score}</a>`);
                            const starClass = `douban_rating_star_${Math.round(douban_rating_score)}`;
                            $("#eba-db-stars").addClass(starClass).show();
                        } else {
                            $("#eba-db-text").html(`<a href="${url}" target="_blank" style="color:#007722; text-decoration:none;">豆瓣暂无评分</a>`);
                        }
                    } else {
                        $("#eba-db-text").text("豆瓣评分: 获取失败");
                    }
                } catch(e) {}
            }
        });
    };

    // 3. 通用查询工厂 (多看、京东、当当)
    const queryeBookApi = (vendor, isbn, metaTitle, metaAuthor) => {
        let t = encodeURIComponent(metaTitle || "");
        let a = encodeURIComponent(metaAuthor || "");
        GM_xmlhttpRequest({
            method: "GET",
            url: `${REST_URL}/${vendor}?isbn=${isbn}&title=${t}&author=${a}&version=1.1.0&r=${Math.random()}`,
            headers: commonHeaders,
            onload: (res) => {
                try {
                    const result = JSON.parse(res.responseText);
                    if (result.errmsg === "" && result.data && result.data.url) {
                        let vendorNames = { 'duokan': '多看阅读', 'jd': '京东读书', 'dangdang': '当当云阅读' };
                        let price = result.data.price ? `￥${result.data.price}` : '查看';
                        lightUpIcon(vendor, result.data.url, `${vendorNames[vendor]} (${price})`);
                    }
                } catch(e) {}
            }
        });
    };

    // 4. 喜马拉雅音频查询 (无 ISBN，仅靠 Title)
    const queryAudioApi = (metaTitle, metaAuthor) => {
        if (!metaTitle) return;
        let t = encodeURIComponent(metaTitle);
        let a = encodeURIComponent(metaAuthor || "");
        GM_xmlhttpRequest({
            method: "GET",
            url: `${REST_URL}/ximalaya?title=${t}&author=${a}&version=1.1.0&r=${Math.random()}`,
            headers: commonHeaders,
            onload: (res) => {
                try {
                    const result = JSON.parse(res.responseText);
                    if (result.errmsg === "" && result.data && result.data.url) {
                        lightUpIcon('ximalaya', result.data.url, `喜马拉雅音频`);
                    }
                } catch(e) {}
            }
        });
    };
    const getIsbn = () => {
        // 逻辑一：固定 XPath 路径
        const xpath = '/html/body/form/table[4]/tbody/tr/td/table[3]/tbody/tr/td/table/tbody/tr/td/table/tbody/tr/td/table[2]/tbody[3]/tr[9]/td[2]/font/text()';
        const node = document.evaluate(xpath, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;

        // 1. 如果 XPath 抓到了节点，直接从中提炼数字（不要求有 "ISBN:" 字样）
        if (node && node.textContent) {
            const clean = node.textContent.replace(/[^\dX]/gi, '').match(/(97[89]\d{10}|\d{9}[\dX])/i);
            if (clean) return clean[0];
        }

        // 2. 逻辑二：XPath 没抓到，则全页扫描（寻找 "ISBN:" 锚点补救）
        const anchorMatch = document.body.innerText.match(/ISBN[:\s]*([0-9\s\-x|;]{10,})/gi);
        if (anchorMatch) {
            // 提纯：优先取 13 位，自动处理 978... 75... 这种双格式
            let found = [];
            anchorMatch.map(m => m.replace(/[^\dX]/gi, '')).forEach(o => {
                let matches = o.match(/(97[89]\d{10}|\d{9}[\dX])/gi);
                if (matches) found.push(...matches);
            });
            if (found.length > 0) {
                const result = found.find(i => i.length === 13) || found[0];
                console.log("[eBooks Assistant] ISBN extracted via regex match:", result);
                return result;
            }
        }
        console.log("[eBooks Assistant] No ISBN could be extracted.");
        return null;
    };
    // 6. 从 isbnsearch.org 获取封面
    const queryIsbnSearchCover = (isbn) => {
        GM_xmlhttpRequest({
            method: "GET",
            url: `https://isbnsearch.org/isbn/${isbn}`,
            onload: function(res) {
                try {
                    let parser = new DOMParser();
                    let doc = parser.parseFromString(res.responseText, "text/html");
                    let imgNode = doc.querySelector('#book .image img');
                    if (imgNode && imgNode.src) {
                        let imgUrl = imgNode.src;
                        if (!imgUrl.startsWith('http')) {
                            imgUrl = 'https://isbnsearch.org' + new URL(imgNode.getAttribute('src'), 'https://isbnsearch.org').pathname;
                        }
                        console.log("[eBooks Assistant] 从 isbnsearch.org 获取到封面:", imgUrl);
                        replaceCover(imgUrl);
                    } else {
                        console.log("[eBooks Assistant] isbnsearch.org 页面未找到封面图片");
                    }
                } catch(e) {
                    console.error("[eBooks Assistant] 解析 isbnsearch.org 封面失败", e);
                }
            }
        });
    };

    // ==========================================
    // 主执行逻辑
    // ==========================================
    const worldcatMain = () => {
        const isbn = getIsbn();
        console.log("[eBooks Assistant] ISBN found:", isbn);
        if (!isbn) {
            console.error("[eBooks Assistant] Execution stopped: No ISBN found on the page.");
            return;
        }

        // 获取书名和作者作备用
        let metaTitle = document.title.split('(')[0].trim() || "";
        let metaAuthor = "";

        // 寻找注入节点：用户指定优先挂载到 "外部資源:" 所在的格子
        let targetNode = null;
        const tds = Array.from(document.querySelectorAll('td'));
        for (const td of tds) {
            if (td.textContent.includes('外部資源:') || td.textContent.includes('外部资源:') || td.textContent.includes('External Resources:')) {
                if (td.nextElementSibling) {
                    targetNode = td.nextElementSibling;
                    console.log("[eBooks Assistant] Found '外部資源:' target node for UI injection.");
                    break;
                }
            }
        }

        if (!targetNode) {
            console.log("[eBooks Assistant] '外部資源:' node not found, falling back to XPath.");
            const injectionXpath = '/html/body/form/table[4]/tbody/tr/td/table[3]/tbody/tr/td/table/tbody/tr/td/table/tbody/tr/td/table[2]/tbody[1]/tr[3]/td[2]';
            targetNode = getElementByXPath(injectionXpath);
            
            if (!targetNode) {
                console.log("[eBooks Assistant] Primary injection XPath failed. Searching for fallback target.");
                // 降级使用其他容器或者直接挂在 body 顶部
                targetNode = document.querySelector('.title-row, .title, .record-title') || document.body;
                if (!targetNode) {
                    console.error("[eBooks Assistant] Execution stopped: Could not find any target node to inject UI.");
                    return;
                }
            }
        }
        console.log("[eBooks Assistant] Target node found, injecting UI...");

        // 初始化 UI
        addNewStyle();
        injectUI(targetNode, isbn);

        // 并行发射 API 请求
        queryIsbnSearchCover(isbn);
        queryWeReadAndPivot(isbn, metaTitle, metaAuthor);
        queryeBookApi('duokan', isbn, metaTitle, metaAuthor);
        queryeBookApi('jd', isbn, metaTitle, metaAuthor);
        queryeBookApi('dangdang', isbn, metaTitle, metaAuthor);
        queryAudioApi(metaTitle, metaAuthor);
    };

    // 启动监听
    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        setTimeout(worldcatMain, 1000);
    } else {
        window.addEventListener('DOMContentLoaded', () => setTimeout(worldcatMain, 1000));
    }

})();